"""Local operator browser interface for the production agent service."""

PAGE = b"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Production Agent</title><style>body{font:16px system-ui;max-width:760px;margin:3rem auto;padding:1rem;background:#f7f9fc;color:#172033}main{background:white;padding:2rem;border-radius:14px}input,textarea,button{font:inherit;display:block;width:100%;box-sizing:border-box;padding:.6rem;margin:.5rem 0 1rem}textarea{min-height:7rem}button{background:#175cd3;color:white;border:0;border-radius:8px;cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eef3fa;padding:1rem}</style></head><body><main><h1>Production Agent</h1><label>API token<input id="token" type="password"></label><label>Prompt<textarea id="prompt"></textarea></label><label>Run ID (optional)<input id="run-id"></label><button id="run">Run agent</button><label>Canary percentage<input id="percent" type="number" min="0" max="100" value="0"></label><button id="rollout">Set rollout</button><button id="metrics">Metrics</button><button id="alerts">Alerts</button><pre id="result" aria-live="polite"></pre></main><script>const token=document.getElementById('token'),result=document.getElementById('result');async function call(path,body){try{const response=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token.value},body:body?JSON.stringify(body):undefined});const text=await response.text();try{result.textContent=JSON.stringify(JSON.parse(text),null,2)}catch{result.textContent=text}}catch(error){result.textContent=String(error)}}document.getElementById('run').onclick=()=>call('/run',{prompt:document.getElementById('prompt').value,run_id:document.getElementById('run-id').value||undefined});document.getElementById('rollout').onclick=()=>call('/rollout',{percent:Number(document.getElementById('percent').value)});document.getElementById('metrics').onclick=()=>call('/metrics');document.getElementById('alerts').onclick=()=>call('/alerts');</script></body></html>"""
